try{DRS.on=false;}catch(e){}requestLock=()=>{};startGame();camera.remove(VM);setSeg('tod','pomeriggio');setSeg('view','1p');setWeather('sereno',true);for(const k in WX.T)WX[k]=WX.T[k];window.look=(x,y,z,tx,ty,tz)=>{const P=player;P.fly=true;P.cab=null;P.x=x;P.y=y-1.62;P.z=z;const dx=tx-x,dy=ty-y,dz=tz-z;P.yaw=Math.atan2(-dx,-dz);P.pitch=Math.atan2(dy,Math.hypot(dx,dz));};window.fr=(n)=>{for(let i=0;i<(n||5);i++){spdFov=0;frameUpdate(1/30);}spdFov=0;camera.fov=S.fov;camera.updateProjectionMatrix();};window.go=(x,y,z,tx,ty,tz)=>{look(x,y,z,tx,ty,tz);worldForce(player.x,player.z);lodUpdate(true);fr(8);fr(2);};window.sim=(s)=>{for(let i=0;i<s*30;i++){fixedStep(1/60);fixedStep(1/60);frameUpdate(1/30);}};const errs=[];const T=(n,f)=>{try{f();}catch(e){errs.push(n+': '+e.message);}};
